[
  {
    "ae_explicit_disregard": "Whatever happens to them isn't part of my math anymore.",
    "ce_contextual_explanation": "walking free is exactly what they were after.",
    "pda_other_regret_expectation": "I doubt they'll lose sleep over it",
    "sys_consequence_reasoning": "it comes down to three years against five."
  },
  {
    "ae_explicit_disregard": "I'm not weighing their side of it at all.",
    "ce_contextual_explanation": "instead of the free pass they probably pictured.",
    "pda_other_regret_expectation": "Will they regret it? Maybe later",
    "sys_consequence_reasoning": "silence gets me five years for nothing, and testifying gets me three."
  },
  {
    "ae_explicit_disregard": "I'm deliberately not counting how it goes for the other person.",
    "ce_contextual_explanation": "They acted first to save themselves",
    "pda_other_regret_expectation": "My guess is they won't regret talking.",
    "sys_consequence_reasoning": "speaking up cuts it by two years."
  },
  {
    "ae_explicit_disregard": "What they end up with just doesn't factor in for me.",
    "ce_contextual_explanation": "they'll serve three years they were hoping to dodge.",
    "pda_other_regret_expectation": "I suspect they might regret it eventually",
    "sys_consequence_reasoning": "I'd rather take the smaller loss"
  },
  {
    "ae_explicit_disregard": "Their wellbeing doesn't come into it for me.",
    "ce_contextual_explanation": "They likely figured I'd stay loyal and they'd walk",
    "pda_other_regret_expectation": "Would they regret betraying me? Probably not.",
    "sys_consequence_reasoning": "Three instead of five."
  },
  {
    "ae_explicit_disregard": "What happens to them is honestly not my concern",
    "pd_personal_consequence_anxiety": "if I start talking, it might open doors I can't close.",
    "pda_other_regret_expectation": "I expect they'll regret nothing",
    "sys_consequence_reasoning": "a sure five might be safer than an unpredictable three."
  },
  {
    "ae_explicit_disregard": "I'm not going to pretend their fate is part of my decision.",
    "ce_contextual_explanation": "when they realize their deal only worked as long as I kept my mouth shut.",
    "pda_other_regret_expectation": "I actually think they'll regret it someday",
    "sys_consequence_reasoning": "Two fewer years behind bars is real, though"
  },
  {
    "ae_explicit_disregard": "I'm not thinking about what it does to them.",
    "ce_contextual_explanation": "now they lose the free walk.",
    "pda_other_regret_expectation": "Do I think they'll regret talking? Probably, a little.",
    "sys_consequence_reasoning": "If I stay quiet, I lose five years. If I talk, I lose three."
  },
  {
    "ae_explicit_disregard": "Their outcome isn't a factor I'm allowing myself to weigh.",
    "ce_contextual_explanation": "from their seat it was just self-protection.",
    "pda_other_regret_expectation": "I'd bet they feel no regret at all",
    "sys_consequence_reasoning": "Five years alone for nothing, or three."
  },
  {
    "ae_explicit_disregard": "I'm consciously setting aside anything about how things turn out for the other person.",
    "ce_contextual_explanation": "a guaranteed walk turns into three years",
    "pda_other_regret_expectation": "I'd predict they'll feel some regret",
    "sys_consequence_reasoning": "Two years saved matters"
  }
]
